selector_to_html = {"a[href=\"#acceleration-term\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">11.3 Acceleration term<a class=\"headerlink\" href=\"#acceleration-term\" title=\"Link to this heading\">\u00b6</a></h3><p>The full one-dimensional momentum equation is:</p>", "a[href=\"moody-diagram.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">The Moody Diagram<a class=\"headerlink\" href=\"#the-moody-diagram\" title=\"Link to this heading\">\u00b6</a></h1><p>The Moody diagram relates the Darcy friction factor, <span class=\"math notranslate nohighlight\">\\(f\\)</span>, to Reynolds number\nand relative surface roughness. Pyskyfire uses this friction factor when it\ncalculates pressure loss in a cooling channel.</p>", "a[href=\"#friction-gradient\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">11.2 Friction gradient<a class=\"headerlink\" href=\"#friction-gradient\" title=\"Link to this heading\">\u00b6</a></h3><p>A geometric path-length factor is computed:</p>", "a[href=\"#coolant-velocity\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">12.2 Coolant velocity<a class=\"headerlink\" href=\"#coolant-velocity\" title=\"Link to this heading\">\u00b6</a></h3><p>The velocity reported at each node is:</p>", "a[href=\"#coolant-velocity-and-reynolds-number\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">8.2 Coolant velocity and Reynolds number<a class=\"headerlink\" href=\"#coolant-velocity-and-reynolds-number\" title=\"Link to this heading\">\u00b6</a></h3><p>The local single-channel flow area is:</p>", "a[href=\"#station-states-along-the-contour\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.4 Station states along the contour<a class=\"headerlink\" href=\"#station-states-along-the-contour\" title=\"Link to this heading\">\u00b6</a></h3><p>With no temperature or enthalpy argument, a getter such as <code class=\"docutils literal notranslate\"><span class=\"pre\">get_T(x)</span></code> solves\nthe rocket problem at the local area ratio:</p>", "a[href=\"#imposed-temperature-and-imposed-enthalpy\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.5 Imposed temperature and imposed enthalpy<a class=\"headerlink\" href=\"#imposed-temperature-and-imposed-enthalpy\" title=\"Link to this heading\">\u00b6</a></h3><p>When a temperature is supplied, for example:</p>", "a[href=\"#hot-gas-side-heat-transfer\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Hot-gas-side heat transfer<a class=\"headerlink\" href=\"#hot-gas-side-heat-transfer\" title=\"Link to this heading\">\u00b6</a></h2><p>The hot-side calculation is performed by:</p>", "a[href=\"#stagnation-temperature\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">12.3 Stagnation temperature<a class=\"headerlink\" href=\"#stagnation-temperature\" title=\"Link to this heading\">\u00b6</a></h3><p>The stagnation temperature is computed from the static coolant temperature and kinetic-energy term:</p>", "a[href=\"#aerothermodynamics-from-thermo-aerothermodynamics\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Aerothermodynamics from <code class=\"docutils literal notranslate\"><span class=\"pre\">thermo.aerothermodynamics</span></code><a class=\"headerlink\" href=\"#aerothermodynamics-from-thermo-aerothermodynamics\" title=\"Link to this heading\">\u00b6</a></h2><p>The regenerative cooling solver needs the hot-gas state along the contour. In the CEA-based workflow, this is provided by the <code class=\"docutils literal notranslate\"><span class=\"pre\">Aerothermodynamics</span></code> class.</p>", "a[href=\"#initialization-from-thrust-and-exit-pressure\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.2 Initialization from thrust and exit pressure<a class=\"headerlink\" href=\"#initialization-from-thrust-and-exit-pressure\" title=\"Link to this heading\">\u00b6</a></h3><p>The alternative constructor is:</p>", "a[href=\"#coolant-film-and-bulk-properties\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">8.1 Coolant film and bulk properties<a class=\"headerlink\" href=\"#coolant-film-and-bulk-properties\" title=\"Link to this heading\">\u00b6</a></h3><p>The film temperature is:</p>", "a[href=\"#coolant-heat-pickup-per-unit-length\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">8.5 Coolant heat pickup per unit length<a class=\"headerlink\" href=\"#coolant-heat-pickup-per-unit-length\" title=\"Link to this heading\">\u00b6</a></h3><p>The coolant-side thermal resistance per unit length is delegated to the cooling-circuit geometry object:</p>", "a[href=\"#darcy-friction-factor\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">11.1 Darcy friction factor<a class=\"headerlink\" href=\"#darcy-friction-factor\" title=\"Link to this heading\">\u00b6</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">fluids</span></code> backend described here is selected explicitly; <strong><code class=\"docutils literal notranslate\"><span class=\"pre\">native</span></code> remains\nthe default</strong>, including for existing validation cases. For an existing thrust\nchamber and boundary conditions:</p>", "a[href=\"#derived-outputs\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">12. Derived outputs<a class=\"headerlink\" href=\"#derived-outputs\" title=\"Link to this heading\">\u00b6</a></h2><p>After all nodes have been marched, the solver calculates several reporting quantities.</p>", "a[href=\"#adiabatic-wall-temperature-and-adiabatic-wall-enthalpy\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.3 Adiabatic-wall temperature and adiabatic-wall enthalpy<a class=\"headerlink\" href=\"#adiabatic-wall-temperature-and-adiabatic-wall-enthalpy\" title=\"Link to this heading\">\u00b6</a></h3><p>Adiabatic-wall temperature is computed using <code class=\"docutils literal notranslate\"><span class=\"pre\">physics.T_aw</span></code>:</p>", "a[href=\"#code-path-overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Code path overview<a class=\"headerlink\" href=\"#code-path-overview\" title=\"Link to this heading\">\u00b6</a></h2><p>The public entry point is:</p>", "a[href=\"../autoapi/pyskyfire/regen/coupled_solver/index.html#pyskyfire.regen.coupled_solver.coupled_steady_heating_analysis\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.coupled_steady_heating_analysis\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">coupled_steady_heating_analysis</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thrust_chamber</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">boundary_conditions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nodes</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">100</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuit_index</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'auto'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../autoapi/pyskyfire/regen/coupled_solver/FilmHeatFluxModel.html#pyskyfire.regen.coupled_solver.FilmHeatFluxModel\" title=\"pyskyfire.regen.coupled_solver.FilmHeatFluxModel\"><span class=\"pre\">FilmHeatFluxModel</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h_liquid_wall</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">Callable</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">DEFAULT_H_LIQUID_WALL</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film_x_array</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">Sequence</span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">solver</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'newton'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">output</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">heat_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pressure_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../autoapi/pyskyfire/regen/coupled_solver/RegenResult.html#pyskyfire.regen.coupled_solver.RegenResult\" title=\"pyskyfire.regen.coupled_solver.RegenResult\"><span class=\"pre\">RegenResult</span></a></span></span></dt><dd><p>Run a steady heating analysis with film cooling, regen cooling, or both.</p></dd>", "a[href=\"#residual-logging\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">13. Residual logging<a class=\"headerlink\" href=\"#residual-logging\" title=\"Link to this heading\">\u00b6</a></h2><p>When residual logging is enabled, every local wall-temperature solve records:</p>", "a[href=\"#hot-side-heat-flux-and-heat-per-unit-length\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.4 Hot-side heat flux and heat per unit length<a class=\"headerlink\" href=\"#hot-side-heat-flux-and-heat-per-unit-length\" title=\"Link to this heading\">\u00b6</a></h3><p>The hot-side wall heat flux is:</p>", "a[href=\"#colburn-coolant-side-heat-transfer-coefficient\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">8.4 Colburn coolant-side heat-transfer coefficient<a class=\"headerlink\" href=\"#colburn-coolant-side-heat-transfer-coefficient\" title=\"Link to this heading\">\u00b6</a></h3><p>The coolant-side heat-transfer coefficient is calculated by <code class=\"docutils literal notranslate\"><span class=\"pre\">physics.h_coolant_colburn</span></code>:</p>", "a[href=\"#bartz-type-enthalpy-driven-coefficient\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.2 Bartz-type enthalpy-driven coefficient<a class=\"headerlink\" href=\"#bartz-type-enthalpy-driven-coefficient\" title=\"Link to this heading\">\u00b6</a></h3><p>The hot-side coefficient is calculated by <code class=\"docutils literal notranslate\"><span class=\"pre\">physics.h_gas_bartz_enthalpy_driven</span></code>:</p>", "a[href=\"#coolant-temperature-marching\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">10. Coolant temperature marching<a class=\"headerlink\" href=\"#coolant-temperature-marching\" title=\"Link to this heading\">\u00b6</a></h2><p>After the wall temperatures are solved at station <code class=\"docutils literal notranslate\"><span class=\"pre\">i</span></code>, the coolant temperature at station <code class=\"docutils literal notranslate\"><span class=\"pre\">i+1</span></code> is updated using the heat absorbed by the coolant in the current cell.</p><p>The continuous energy equation is:</p>", "a[href=\"#local-gas-side-geometry-and-state\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.1 Local gas-side geometry and state<a class=\"headerlink\" href=\"#local-gas-side-geometry-and-state\" title=\"Link to this heading\">\u00b6</a></h3><p>The hot-gas-side hydraulic diameter is approximated as twice the local chamber radius:</p>", "a[href=\"#boundary-conditions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Boundary conditions<a class=\"headerlink\" href=\"#boundary-conditions\" title=\"Link to this heading\">\u00b6</a></h2><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">BoundaryConditions</span></code> class stores the inlet state of one cooling circuit:</p>", "a[href=\"../autoapi/pyskyfire/common/friction/index.html#pyskyfire.common.friction.friction_pressure_gradient\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.friction.friction_pressure_gradient\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">friction_pressure_gradient</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ReDh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">velocity</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_curv</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">np.inf</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">curvature_correction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">model</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the irreversible pressure gradient <code class=\"docutils literal notranslate\"><span class=\"pre\">dp/ds</span></code> [Pa m\u207b\u00b9].</p><p>This is the friction term of the one-dimensional momentum equation only.\nThe reversible acceleration term <code class=\"docutils literal notranslate\"><span class=\"pre\">-rho</span> <span class=\"pre\">u</span> <span class=\"pre\">du/ds</span></code> depends on the state at\nboth ends of a segment rather than on a local gradient, so the caller\napplies it while marching.</p></dd>", "a[href=\"#coolant-side-heat-transfer\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Coolant-side heat transfer<a class=\"headerlink\" href=\"#coolant-side-heat-transfer\" title=\"Link to this heading\">\u00b6</a></h2><p>The coolant-side coefficient is calculated by:</p>", "a[href=\"#regenerative-cooling\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Regenerative Cooling<a class=\"headerlink\" href=\"#regenerative-cooling\" title=\"Link to this heading\">\u00b6</a></h1><p>This page explains the regenerative cooling model implemented in <code class=\"docutils literal notranslate\"><span class=\"pre\">pyskyfire.regen</span></code>. It traces the path through <code class=\"docutils literal notranslate\"><span class=\"pre\">coupled_solver.py</span></code>, shows how the solver calls the equations in <code class=\"docutils literal notranslate\"><span class=\"pre\">physics.py</span></code>, and explains how the hot-gas aerothermodynamic properties are prepared by <code class=\"docutils literal notranslate\"><span class=\"pre\">pyskyfire.thermo.aerothermodynamics</span></code>.</p><p>The model is a quasi-one-dimensional steady heat-exchanger calculation. At each axial station, it balances three heat-transfer paths:</p>", "a[href=\"#attaching-the-contour\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.3 Attaching the contour<a class=\"headerlink\" href=\"#attaching-the-contour\" title=\"Link to this heading\">\u00b6</a></h3><p>After construction, the method:</p>", "a[href=\"#wall-interface-temperature-array\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">12.4 Wall-interface temperature array<a class=\"headerlink\" href=\"#wall-interface-temperature-array\" title=\"Link to this heading\">\u00b6</a></h3><p>The returned <code class=\"docutils literal notranslate\"><span class=\"pre\">T</span></code> array has shape:</p>", "a[href=\"#curvature-factor\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">8.3 Curvature factor<a class=\"headerlink\" href=\"#curvature-factor\" title=\"Link to this heading\">\u00b6</a></h3><p>The local channel radius of curvature is:</p>", "a[href=\"#coolant-pressure-marching\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">11. Coolant pressure marching<a class=\"headerlink\" href=\"#coolant-pressure-marching\" title=\"Link to this heading\">\u00b6</a></h2><p>The solver marches <strong>static</strong> pressure, because static pressure is what the\nmomentum equation governs and what test data and the reference RL10 models\nreport. Stagnation pressure is carried alongside as\n<span class=\"math notranslate nohighlight\">\\(p_0 = p + \\tfrac{1}{2}\\rho_c u_c^2\\)</span>.</p><p>The irreversible part of the update is calculated by:</p>", "a[href=\"#segment-update\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">11.4 Segment update<a class=\"headerlink\" href=\"#segment-update\" title=\"Link to this heading\">\u00b6</a></h3><p>The static update is:</p>", "a[href=\"#assumptions-and-implementation-details\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">14. Assumptions and implementation details<a class=\"headerlink\" href=\"#assumptions-and-implementation-details\" title=\"Link to this heading\">\u00b6</a></h2><p>The current regenerative cooling solver is an engineering heat-exchanger model. Its main assumptions are:</p>", "a[href=\"#local-wall-temperature-solve\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">9. Local wall-temperature solve<a class=\"headerlink\" href=\"#local-wall-temperature-solve\" title=\"Link to this heading\">\u00b6</a></h2><p>At each axial station <code class=\"docutils literal notranslate\"><span class=\"pre\">i</span></code>, the solver forms three per-cell heat flows:</p>", "a[href=\"#symbols-and-sign-conventions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Symbols and sign conventions<a class=\"headerlink\" href=\"#symbols-and-sign-conventions\" title=\"Link to this heading\">\u00b6</a></h2><p>The most important local variables are:</p>", "a[href=\"#wall-conduction\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Wall conduction<a class=\"headerlink\" href=\"#wall-conduction\" title=\"Link to this heading\">\u00b6</a></h2><p>Wall conduction is calculated by:</p>", "a[href=\"#heat-transfer-coefficients-and-adiabatic-wall-temperature\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">12.5 Heat-transfer coefficients and adiabatic-wall temperature<a class=\"headerlink\" href=\"#heat-transfer-coefficients-and-adiabatic-wall-temperature\" title=\"Link to this heading\">\u00b6</a></h3><p>For each node, the solver recomputes and stores:</p>", "a[href=\"../autoapi/pyskyfire/index.html#module-pyskyfire\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire<a class=\"headerlink\" href=\"#module-pyskyfire\" title=\"Link to this heading\">\u00b6</a></h1><p>pyskyfire - A Python library for rocket engine simulation and design.</p>", "a[href=\"#summary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">16. Summary<a class=\"headerlink\" href=\"#summary\" title=\"Link to this heading\">\u00b6</a></h2><p>The regenerative cooling solver couples a CEA-based hot-gas property model to a one-dimensional cooling-channel heat-exchanger calculation. The solver walks along the selected cooling circuit, solves a local nonlinear balance for the hot- and cold-side wall temperatures, and then marches coolant temperature and pressure downstream.</p><p>At each station, the central balance is:</p>", "a[href=\"#continuation-below-the-cea-temperature-boundary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.6 Continuation below the CEA temperature boundary<a class=\"headerlink\" href=\"#continuation-below-the-cea-temperature-boundary\" title=\"Link to this heading\">\u00b6</a></h3><p>CEA becomes unreliable at low temperature, so states below\n<code class=\"docutils literal notranslate\"><span class=\"pre\">minimum_cea_temperature</span></code> (200 K by default, configurable on the constructor)\nare not solved directly. Instead, the properties are continued along their\nright-hand tangent at the boundary <span class=\"math notranslate nohighlight\">\\(T_b\\)</span>. Three TP solves are taken at\n<span class=\"math notranslate nohighlight\">\\(T_b,\\ T_b + \\Delta T,\\ T_b + 2\\Delta T\\)</span>, and a second-order one-sided\nderivative is formed:</p>", "a[href=\"#initialization-from-thrust-area-ratio-and-characteristic-length\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.1 Initialization from thrust, area ratio, and characteristic length<a class=\"headerlink\" href=\"#initialization-from-thrust-area-ratio-and-characteristic-length\" title=\"Link to this heading\">\u00b6</a></h3><p>One constructor is:</p>", "a[href=\"#marching-grid-and-unknowns-in-solver-py\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Marching grid and unknowns in <code class=\"docutils literal notranslate\"><span class=\"pre\">solver.py</span></code><a class=\"headerlink\" href=\"#marching-grid-and-unknowns-in-solver-py\" title=\"Link to this heading\">\u00b6</a></h2><p>The cooling solver reads the selected cooling circuit:</p>", "a[href=\"../autoapi/pyskyfire/regen/coupled_solver/RegenResult.html#pyskyfire.regen.coupled_solver.RegenResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.RegenResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RegenResult</span></span></dt><dd><p>Regenerative-cooling result with optional film-cooling data.</p><p>The coolant-state fields (<code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_enthalpy</span></code> onwards) describe the bulk\ncoolant along the circuit. <code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_enthalpy</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_quality</span></code> are\nall-<code class=\"docutils literal notranslate\"><span class=\"pre\">nan</span></code> when the coolant fell back to the temperature march, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_quality</span></code> is <code class=\"docutils literal notranslate\"><span class=\"pre\">nan</span></code> at any station outside the boiling dome \u2013\nincluding supercritical stations, where no dome exists. Use\n<code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_phase</span></code> to tell those cases apart.</p></dd>", "a[href=\"#heat-flux\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">12.1 Heat flux<a class=\"headerlink\" href=\"#heat-flux\" title=\"Link to this heading\">\u00b6</a></h3><p>At each station:</p>", "a[href=\"#returned-data-structure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">15. Returned data structure<a class=\"headerlink\" href=\"#returned-data-structure\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">coupled_steady_heating_analysis</span></code> returns a <code class=\"docutils literal notranslate\"><span class=\"pre\">RegenResult</span></code> produced by <code class=\"docutils literal notranslate\"><span class=\"pre\">solve_coupled_heat_exchanger</span></code>. Its core fields are:</p>", "a[href=\"../autoapi/pyskyfire/common/index.html#module-pyskyfire.common\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common<a class=\"headerlink\" href=\"#module-pyskyfire.common\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
